-- Identity columns: ALTER COLUMN SET/DROP DEFAULT rejection (issue #1458)
-- PostgreSQL rejects SET DEFAULT and DROP DEFAULT on identity columns.

-- 1. SET DEFAULT on GENERATED ALWAYS AS IDENTITY → error
CREATE TABLE t1458_id1 (id INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, v TEXT);
ALTER TABLE t1458_id1 ALTER COLUMN id SET DEFAULT 42;

-- 2. DROP DEFAULT on GENERATED BY DEFAULT AS IDENTITY → error with hint
CREATE TABLE t1458_id2 (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, v TEXT);
ALTER TABLE t1458_id2 ALTER COLUMN id DROP DEFAULT;

-- 3. Unmodified identity INSERT regression guard
INSERT INTO t1458_id1 (v) VALUES ('a');
SELECT id, v FROM t1458_id1;

-- 4. ADD COLUMN identity backfill regression guard (#1587)
CREATE TABLE t1458_id3 (v TEXT);
INSERT INTO t1458_id3 (v) VALUES ('existing');
ALTER TABLE t1458_id3 ADD COLUMN id INT GENERATED BY DEFAULT AS IDENTITY;
SELECT v, id FROM t1458_id3;

-- Cleanup
DROP TABLE IF EXISTS t1458_id1;
DROP TABLE IF EXISTS t1458_id2;
DROP TABLE IF EXISTS t1458_id3;
